import { test } from 'node:test';
import assert from 'assert';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices: returns invoices with dueDate before asOf', () => {
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv1Result.ok, true);
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv2Result.ok, true);
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 2);
});

test('overdueInvoices: filters out draft invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv1Result.ok, true);
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv2Result.ok, true);

  const invoices = [inv1Issued.value, inv2Result.value];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, inv1Issued.value.number);
});

test('overdueInvoices: filters out invoices with dueDate on or after asOf', () => {
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv1Result.ok, true);
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(inv2Result.ok, true);
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  // inv1 due date is 2026-10-31 (NET30), inv2 due date is 2026-11-19 (NET30)
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, inv1Issued.value.number);
});

test('overdueInvoices: includes all required fields', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  const invoices = [issued.value];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  const overdue = result[0];
  assert.equal(typeof overdue.number, 'string');
  assert.equal(typeof overdue.customerId, 'string');
  assert.equal(typeof overdue.dueDate, 'string');
  assert.equal(typeof overdue.daysOverdue, 'number');
  assert.equal(typeof overdue.due, 'number');
});

test('overdueInvoices: calculates daysOverdue correctly', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  const invoices = [issued.value];
  // Due date is 2026-10-31, asOf is 2026-11-15 = 15 days overdue
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 15);
});

test('overdueInvoices: calculates due amount from balanceDue', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  const invoices = [issued.value];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  // DEV-HOUR qty 2: €190.00, VAT 21% = €39.90, total = €229.90 = 22990 cents
  assert.equal(result[0].due, 22990);
});

test('overdueInvoices: subtracts payments from due', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  let inv = issued.value;
  const paymentResult = recordPayment(inv, { amount: 10000, date: '2026-10-15' });
  assert.equal(paymentResult.ok, true);
  inv = paymentResult.value;

  const invoices = [inv];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  // Total 22990, paid 10000, due 12990
  assert.equal(result[0].due, 12990);
});

test('overdueInvoices: sorts by daysOverdue descending (most overdue first)', () => {
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(inv1Result.ok, true);
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(inv2Result.ok, true);
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  // inv1 due 2026-10-31 (15 days overdue on 2026-11-15)
  // inv2 due 2026-11-09 (6 days overdue on 2026-11-15)
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 15);
  assert.equal(result[1].daysOverdue, 6);
});

test('overdueInvoices: includes partially_paid invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  let inv = issued.value;
  const paymentResult = recordPayment(inv, { amount: 5000, date: '2026-10-15' });
  assert.equal(paymentResult.ok, true);
  inv = paymentResult.value; // Now partially_paid

  const invoices = [inv];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 1);
  assert.equal(result[0].status, undefined); // status not included in result
});

test('overdueInvoices: filters out paid invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  let inv = issued.value;
  const paymentResult = recordPayment(inv, { amount: 22990, date: '2026-10-15' });
  assert.equal(paymentResult.ok, true);
  inv = paymentResult.value; // Now paid

  const invoices = [inv];
  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 0);
});

test('overdueInvoices: returns empty array when no overdue invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(invResult.ok, true);
  const issued = issueInvoice(invResult.value, []);

  const invoices = [issued.value];
  // Due date is 2026-11-19, asOf is before that
  const result = overdueInvoices(invoices, '2026-11-10');

  assert.equal(result.length, 0);
});

test('overdueInvoices: handles multiple overdue invoices', () => {
  const invoices = [];
  const existingNumbers = [];

  for (let i = 0; i < 3; i++) {
    const invResult = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-10-0${i + 1}`,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(invResult.ok, true);
    const issued = issueInvoice(invResult.value, existingNumbers);
    invoices.push(issued.value);
    existingNumbers.push(issued.value.number);
  }

  const result = overdueInvoices(invoices, '2026-11-15');

  assert.equal(result.length, 3);
  // Verify sorted by daysOverdue descending
  for (let i = 0; i < result.length - 1; i++) {
    assert(result[i].daysOverdue >= result[i + 1].daysOverdue);
  }
});

