test('vatSummary: calculates base correctly with discount', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DEV-HOUR', qty: 2, discountPercent: 10 }, // 21% VAT
